"use server";

/**
 * Invites one member; enforces the seat quota and the invite rate limit.
 *
 * Owner D. Pending invitations count against `seats` — otherwise an org on the
 * free plan could queue fifty invitations and blow past three seats the moment
 * they are accepted.
 *
 * Must call (do not reimplement): inviteMemberSchema, can, getPlanLimits,
 * consumeRateLimit, getActor, toActionResult
 */

import {
  ForbiddenActionError,
  PlanLimitError,
  RateLimitedError,
} from "@/actions/_lib/action-errors";
import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inviteMemberSchema, type InviteMemberInput } from "@/schemas/member";
import { inviteMember } from "@/server/services/invitation-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Invitation } from "@/types/member";

const INVITE_BUCKET = "member:invite";

const run = withAction<typeof inviteMemberSchema, Invitation>(
  inviteMemberSchema,
  async (raw, actor) => {
    const input = raw as InviteMemberInput;

    const allowed = can(actor, "member:invite", {
      kind: "member",
      orgId: input.orgId,
      memberId: PENDING_MEMBER_ID,
      targetUserId: actor.userId,
      targetRole: input.role,
    });
    if (!allowed) {
      throw new ForbiddenActionError("member:invite");
    }

    const verdict = await consumeRateLimit(input.orgId, INVITE_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(INVITE_BUCKET, verdict.resetAt);
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.seatsUsed + 1 > limits.seats) {
      throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
    }

    const invitation = await inviteMember(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return invitation;
  },
  { revalidate: ["members", "invitations"], cacheProfile: "minutes" },
);

export async function inviteMemberAction(raw: unknown): Promise<ActionResult<Invitation>> {
  return run(raw);
}
"use server";

/**
 * Accepts an invitation token and creates the membership.
 *
 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
 * org, so there is no `Actor` to resolve and the action cannot use
 * `withAction()`. The seat quota is re-checked at acceptance time because the
 * organization may have filled up since the invitation was sent.
 *
 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
 */

import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { acceptInvitationTokenSchema } from "@/schemas/invitation";
import { acceptInvitation } from "@/server/services/invitation-service";
import { resolveActor } from "@/server/services/member-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Member } from "@/types/member";

export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
  const parsed = acceptInvitationTokenSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
    }

    const member = await acceptInvitation(principal.userId, parsed.data);
    await assertSeatAvailable(member);

    return { ok: true, data: member, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

/**
 * Confirms the newly created membership still fits the plan. Reading usage
 * requires an actor inside the org, which only exists once the membership row
 * has been written — hence the check runs after `acceptInvitation`.
 */
async function assertSeatAvailable(member: Member): Promise<void> {
  const actor = await resolveActor(member.userId, member.orgId);
  if (actor === null) {
    throw new UnauthorizedActionError("That invitation is no longer valid.");
  }

  const summary = await getOrganizationSummary(actor, member.orgId);
  const limits = getPlanLimits(summary.organization.plan);
  if (summary.usage.seatsUsed > limits.seats) {
    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
  }
}
"use server";

/**
 * Removes a member (soft delete) and frees the seat.
 *
 * Owner D. The membership row is archived rather than deleted so that issues
 * and comments authored by the person keep resolving their author.
 *
 * Must call (do not reimplement): removeMemberSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { removeMemberSchema, type RemoveMemberInput } from "@/schemas/member";
import { removeMember } from "@/server/services/member-service";
import type { ActionResult } from "@/types/api";
import type { Member } from "@/types/member";

const run = withAction<typeof removeMemberSchema, Member>(
  removeMemberSchema,
  async (raw, actor) => {
    const input = raw as RemoveMemberInput;

    const allowed = can(actor, "member:remove", {
      kind: "member",
      orgId: input.orgId,
      memberId: input.memberId,
      targetUserId: actor.userId,
      targetRole: actor.role,
    });
    if (!allowed) {
      throw new ForbiddenActionError("member:remove");
    }

    const member = await removeMember(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return member;
  },
  { revalidate: ["members"], cacheProfile: "minutes" },
);

export async function removeMemberAction(raw: unknown): Promise<ActionResult<Member>> {
  return run(raw);
}
"use server";

/**
 * Changes a member's role, keeping at least one owner.
 *
 * Owner D. Two guards that are easy to get wrong: nobody may grant a role above
 * their own (`hasRoleAtLeast`), and the last owner may not be demoted —
 * `MemberService.assertLastOwnerRetained` owns that second rule because it
 * needs to count owners.
 *
 * Must call (do not reimplement): updateMemberRoleSchema, can, hasRoleAtLeast,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  updateMemberRoleSchema,
  type UpdateMemberRoleInput,
} from "@/schemas/member";
import {
  assertLastOwnerRetained,
  updateMemberRole,
} from "@/server/services/member-service";
import type { ActionResult } from "@/types/api";
import { hasRoleAtLeast, type Member } from "@/types/member";

const run = withAction<typeof updateMemberRoleSchema, Member>(
  updateMemberRoleSchema,
  async (raw, actor) => {
    const input = raw as UpdateMemberRoleInput;

    const allowed = can(actor, "member:update_role", {
      kind: "member",
      orgId: input.orgId,
      memberId: input.memberId,
      targetUserId: actor.userId,
      targetRole: input.role,
    });
    if (!allowed) {
      throw new ForbiddenActionError("member:update_role");
    }

    // Privilege escalation guard: an admin cannot mint an owner.
    if (!hasRoleAtLeast(actor.role, input.role)) {
      throw new ForbiddenActionError("member:update_role");
    }

    await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

    const member = await updateMemberRole(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return member;
  },
  { revalidate: ["members"], cacheProfile: "minutes" },
);

export async function updateMemberRoleAction(raw: unknown): Promise<ActionResult<Member>> {
  return run(raw);
}
/**
 * Credential login, registration and password reset. No third-party provider.
 *
 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
 *
 * Note: `TaskflowEventMap` has no authentication event and the type is part of
 * the frozen contract, so the declared `emit` is not reachable from here.
 * Registration still publishes `member.joined` — through
 * `OrganizationService.createOrganization`, which owns that membership row.
 */
import {
  hashPassword,
