  async function memberOf(tenant: Awaited<ReturnType<typeof createTenant>>, role: "owner" | "admin" | "member" | "viewer") {
    const found = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
    if (!found) throw new Error(`fixture ${role} missing`);
    return found;
  }

  // The free plan's three seats are held by owner, admin and member; the viewer is free.
  it("refuses to turn a viewer into a billable role on a full plan", async () => {
    const tenant = await createTenant("member-seat-full", "free");
    const viewer = await memberOf(tenant, "viewer");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    const after = await memberOf(tenant, "viewer");
    expect(after.role).toBe("viewer");
  });

  it("promotes a viewer while the plan has a free seat", async () => {
    const tenant = await createTenant("member-seat-room", "growth");
    const viewer = await memberOf(tenant, "viewer");

    const updated = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
      role: "admin",
    });
    expect(updated.role).toBe("admin");
  });

  it("never refuses a change between billable roles or to viewer on a full plan", async () => {
    const tenant = await createTenant("member-seat-free-moves", "free");
    const admin = await memberOf(tenant, "admin");
    const member = await memberOf(tenant, "member");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "admin",
      }),
    ).resolves.toMatchObject({ role: "admin" });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  it("counts pending billable invitations, but not pending viewer ones", async () => {
    const tenant = await createTenant("member-seat-pending", "free");
    const viewer = await memberOf(tenant, "viewer");
    const member = await memberOf(tenant, "member");

    // Freeing a seat lets the viewer be promoted in principle...
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
      role: "viewer",
    });

    // ...a pending viewer invite does not take it back...
    await invitationService.inviteMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      email: "pending-viewer@member-seat-pending.test",
      role: "viewer",
    });

    // ...but a pending billable invite does.
    await invitationService.inviteMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      email: "pending-member@member-seat-pending.test",
      role: "member",
    });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
  });
});
'''
