cat > tests/services/usage-service.test.ts <<'EOF'
/**
 * The seat counter: billable roles only, and the incremental adjustments made
 * as members join, change role and are removed must always agree with a full
 * recount.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as memberService from "@/server/services/member-service";
import { createOrganization } from "@/server/services/organization-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Role } from "@/types/member";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerUsageListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

/** The cached counter, then the true recount — which must be the same number. */
async function seatCounters(orgId: OrgId): Promise<{ cached: number; recount: number }> {
  const cached = (await usageRepo.getUsage(orgId)).seatsUsed;
  const recount = (await usageRepo.recomputeUsage(orgId)).seatsUsed;
  return { cached, recount };
}

async function join(orgId: OrgId, slug: string, role: Role) {
  const user = await userRepo.insertUser({
    email: `${role}-${Math.random().toString(36).slice(2)}@${slug}.test`,
    name: `${slug} ${role}`,
    passwordHash: "seed",
  });
  const member = await memberRepo.insertMember(orgId, user.id, role, null);
  await emit("member.joined", {
    orgId,
    actorId: user.id,
    occurredAt: member.createdAt,
    memberId: member.id,
    userId: user.id,
    role,
  });
  return member;
}

describe("services/usage-service seat counter", () => {
  it("recounts billable active members only", async () => {
    const tenant = await createTenant("usage-recount", "growth");

    const { recount } = await seatCounters(tenant.org.id);
    expect(recount).toBe(3);
  });

  it("gives a new organization exactly its owner's seat", async () => {
    const owner = await userRepo.insertUser({
      email: "founder@usage-create.test",
      name: "Founder",
      passwordHash: "seed",
    });
    const org = await createOrganization(owner.id, {
      name: "Usage create",
      slug: "usage-create",
      plan: "free",
    });

    const { cached, recount } = await seatCounters(org.id);
    expect(recount).toBe(1);
    expect(cached).toBe(1);
  });

  it("adds a seat when a billable member joins and none for a viewer", async () => {
    const tenant = await createTenant("usage-join", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);

    await join(tenant.org.id, "usage-join", "viewer");
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 3, recount: 3 });

    await join(tenant.org.id, "usage-join", "member");
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 4, recount: 4 });
  });

  it("follows role changes across the billable boundary", async () => {
    const tenant = await createTenant("usage-role", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!viewer || !member) throw new Error("fixture members missing");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
      role: "admin",
    });
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 4, recount: 4 });

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
      role: "admin",
    });
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 4, recount: 4 });

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
      role: "viewer",
    });
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 3, recount: 3 });
  });

  it("frees a seat only when a billable member is removed", async () => {
    const tenant = await createTenant("usage-remove", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!viewer || !admin) throw new Error("fixture members missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 3, recount: 3 });

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 2, recount: 2 });

    // Removing the same member again must not free a second seat.
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });
    await expect(seatCounters(tenant.org.id)).resolves.toEqual({ cached: 2, recount: 2 });
  });
});
EOF
